def test_modules(tests_dir):
    """Inventory every test file before discovery, including files unittest would silently skip."""
    root = Path(tests_dir)
    missing = [folder for folder in FOLDERS if not (root / folder / '__init__.py').is_file()]
    if missing:
        raise ValueError('Missing test folder/package: ' + ', '.join(missing))
    modules = set()
    for path in sorted(root.rglob('test_*.py')):
        relative = path.relative_to(root)
        if len(relative.parts) < 2 or relative.parts[0] not in FOLDERS:
            raise ValueError('Test outside tier folders: ' + relative.as_posix())
        for package in relative.parents:
            if package != Path('.') and not (root / package / '__init__.py').is_file():
                raise ValueError('Missing test package: ' + package.as_posix())
        modules.add('.'.join(relative.with_suffix('').parts))
    return modules

def discover(loader=None):
    loader = loader or unittest.TestLoader()
    expected = test_modules(TESTS)
    tests = list(flatten(loader.discover(str(TESTS), pattern='test_*.py', top_level_dir=str(TESTS))))
    if loader.errors:
        return tests  # the caller reports the original import errors
    present = {module_of(test) for test in tests}
    if expected != present:
        raise ValueError('Test population mismatch. Missing: ' + ', '.join(sorted(expected - present))
                         + '; unexpected: ' + ', '.join(sorted(present - expected)))
    duplicates = sorted(identifier for identifier, count in Counter(test.id() for test in tests).items() if count > 1)
    if duplicates:
        raise ValueError('Duplicate test IDs: ' + ', '.join(duplicates))
    return tests

def wait_for_worker(job, *, pause=None):
    """Wait for the root and owned children; elapsed time never terminates a test."""
    pause = pause or time.sleep
    while not (job.wait(0) and _empty(job)):
        pause(.05)

def _edition():
    return {path.relative_to(SCRIPTS).as_posix(): hashlib.sha256(path.read_bytes()).hexdigest()
            for path in sorted(SCRIPTS.rglob('*.py')) if '__pycache__' not in path.parts}

def closing_eligible(args, clean, missing, plan):
    """A run that may close a sub-stage or region (A29): the whole T3, clean, fully measured, nothing reused."""
    return bool(not args.tests and not args.match and clean and not missing and plan is not None and not plan.reuse)

def functions(tree):
    """[(key, node)] for every function in ``tree``, in source order."""
    found, seen = [], Counter()

    def visit(node, prefix):
        for child in ast.iter_child_nodes(node):
            if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
                name = prefix + child.name
                seen[name] += 1
                found.append((name if seen[name] == 1 else f'{name}#{seen[name]}', child))
                visit(child, name + '.<locals>.')
            elif isinstance(child, ast.ClassDef):
                visit(child, prefix + child.name + '.')
            else:
                visit(child, prefix)

    visit(tree, '')
    return found

def tests_for(entry, current_blob, key, layer):
    """(test ids as ordinals, fallback folders) for the function ``key`` (see module docstring)."""
    from support.selection import LAYER_FOLDERS, SELECTABLE
    folders = tuple(LAYER_FOLDERS.get(layer, SELECTABLE))
    if entry is None or 'functions' not in entry:
        return set(), folders
    ordinals = set(entry['functions'].get(key.split('#', 1)[0], ()))
    if ordinals or entry.get('blob') == current_blob:
        return ordinals, ()
    return set(), folders

def passed(report):
    """A zero survivor count cannot cover failed measurement or untested functions."""
    return (report['unreasoned_entries'] == 0 and not report['baseline_failing']
            and not any(report['counts'].get(name, 0)
                        for name in ('execution_error', 'mutation_error', 'not_executed')))

def gate(files, layers, scripts_prefix):
    """Branch-reach gate over coverage JSON ``files`` (repo-relative keys) for the gated layers.

    ``layers`` maps scripts-relative module paths to layers (``do_math.layers.LAYERS``);
    ``scripts_prefix`` is the repo-relative path of ``scripts/``. A judged module
    absent from ``files`` was never measured and fails with every line unknown.
    """
    modules, excluded = {}, 0
    judged = sorted(module for module, layer in layers.items() if layer in GATED_LAYERS)
    for module in judged:
        entry = files.get(f'{scripts_prefix}/{module}')
        if entry is None:
            modules[module] = {'layer': layers[module], 'unmeasured': True, 'missing_branches': [], 'missing_lines': []}
            continue
        excluded += len(entry.get('excluded_lines', []))
        branches, lines = entry.get('missing_branches', []), entry.get('missing_lines', [])
        if branches or lines:
            modules[module] = {'layer': layers[module], 'missing_branches': branches, 'missing_lines': lines}
    return {'passed': not modules, 'judged_modules': len(judged), 'modules_with_gaps': len(modules),
            'missing_branches': sum(len(m['missing_branches']) for m in modules.values()),
            'missing_lines': sum(len(m['missing_lines']) for m in modules.values()),
            'unmeasured_modules': sorted(m for m, value in modules.items() if value.get('unmeasured')),
            'excluded_lines': excluded, 'modules': modules}

def build_index(entered, tests, opens, import_opens, blobs, commit, created=None, scripts_prefix=None, *,
                input_dependencies):
    """The selection index from the recorder's ``entered`` ({label: [[repo path, function key], ...]}).

    ``tests`` is the ordered list of test ids that ran; ``opens`` maps a context to
    the non-Python paths opened under it; ``import_opens`` maps such a path to the
    modules that opened it at import; input_dependencies separately records
    inputs of shared producers actually consumed by a label. Readers union these
    relations without asserting that a consumer opened the file. ``blobs`` maps every tracked path (all
    scripts/ .py and every opened input) to its git blob id. Every measured .py
    under ``scripts/`` gets ``functions``, empty when no test entered one.
    """
    scripts_prefix = scripts_prefix or SCRIPTS.relative_to(repository_root()).as_posix()
    ordinal = {test: index for index, test in enumerate(tests)}
    tests_by_module = defaultdict(set)
    for test, index in ordinal.items():
        tests_by_module[test.rsplit('.', 2)[0]].add(index)
    entries = {path: {'blob': blob} for path, blob in blobs.items()}
    functions = defaultdict(lambda: defaultdict(set))
    for label in entered:
        if label.startswith(SHARED):
            continue
        credited = _credited(label, tests_by_module, ordinal)
        if credited:
            for path, key in credited_functions(entered, label):
                functions[path][key] |= credited
    for path, entry in entries.items():
        if path.endswith('.py') and path.startswith(scripts_prefix + '/') and not _test_module(path, scripts_prefix):
            entry['functions'] = {key: sorted(o) for key, o in sorted(functions.get(path, {}).items())}
    readers = defaultdict(set)
    for records in (opens, input_dependencies):
        for context, paths in records.items():
            for path in paths:
                readers[path] |= _credited(context, tests_by_module, ordinal)
    for path, openers in import_opens.items():
        for opener in openers:
            module = _test_module(opener, scripts_prefix)
            readers[path] |= tests_by_module.get(module, set()) if module else {
                o for ordinals in functions.get(opener, {}).values() for o in ordinals}
    for path, credited in readers.items():
        if path in entries:  # an opened path without a blob no longer exists or is untracked scratch
            entries[path]['readers'] = sorted(credited)
    return {'format': FORMAT, 'commit': commit,
            'created': created or datetime.now(timezone.utc).isoformat(timespec='seconds'),
            'tests': list(tests), 'files': dict(sorted(entries.items()))}

def plan(records, universe, existing, current, scripts_prefix, *, coverage_version, full=False):
    """The plan for a T3 run over test modules ``universe`` (see the module docstring for the rules).

    ``records`` is the stored record (``read``) or empty; ``existing`` holds
    every T3 test module of the tree now; ``current`` answers ``blobs(paths)``
    (a path's git blob, None when absent) and ``digests(path)``
    (``code_digests`` of the file, None when absent).
    """
    stored = (records or {}).get('modules', {})

    def everything(reason):
        return Plan('full', reason, universe, (), set(stored))
    if full:
        return everything('--full')
    if not records or records.get('format') != FORMAT:
        return everything('no store')
    if records.get('coverage') != coverage_version:
        return everything(f"store of coverage {records.get('coverage')}")
    runner = [f'{scripts_prefix}/{name}' for name in RUNNER]
    paths = set(runner) | set(records['import_inputs'])
    for module in universe & set(stored):
        paths.add(test_module_path(scripts_prefix, module))
        paths |= set(stored[module]['inputs'])
    blobs = current.blobs(sorted(paths))
    if runner_marks(current, runner) != {path: records['runner'].get(path) for path in runner}:
        return everything('the runner changed')
    digests = {}

    def digest_of(path):
        if path not in digests:
            digests[path] = current.digests(path)
        return digests[path]
    for path, top in sorted(records['tops'].items()):
        now = digest_of(path)
        if now is None or now['top'] != top:
            return everything(f'module- or class-level code changed: {path}')
    for path, blob in sorted(records['import_inputs'].items()):
        if blobs[path] != blob:
            return everything(f'an input read at import changed: {path}')
    measure, reuse, why = set(), set(), {}
    for module in sorted(universe):
        snapshot = stored.get(module)
        reason = None
        if snapshot is None:
            reason = 'new to the store'
        elif blobs[test_module_path(scripts_prefix, module)] != snapshot['blob']:
            reason = 'its file changed'
        else:
            for path, functions in sorted(snapshot['functions'].items()):
                now = digest_of(path)
                changed = [name for name, digest in sorted(functions.items())
                           if now is None or now['functions'].get(name) != digest]
                if changed:
                    reason = f'entered {path}:{changed[0]} changed'
                    break
            else:
                changed = sorted(path for path, blob in snapshot['inputs'].items() if blobs[path] != blob)
                if changed:
                    reason = f'input {changed[0]} changed'
        if reason:
            measure.add(module)
            why[module] = reason
        else:
            reuse.add(module)
    return Plan('incremental', f'{len(measure)} measured, {len(reuse)} reused', measure, reuse,
                set(stored) - set(existing), why)

def read(store):
    """The stored record, or {} when there is none or it does not read."""
    try:
        return json.loads((Path(store) / RECORDS).read_text(encoding='utf-8'))
    except (FileNotFoundError, ValueError):
        return {}

def run_case(destination, case, *, ports, provider, model, effort, only_assigned, scholarly=False, codex_home, environment, host_id):
    root = destination / case
    workspace = root / "workspace"
    workspace.mkdir(parents=True)
    nonce = ports.clock.random_hex(16)
    schema = {"type": "object", "additionalProperties": False,
              "properties": {"status": {"type": "string", "const": "CLI_OK"},
                             "nonce": {"type": "string", "const": nonce},
                             "phase": {"type": "string", "enum": ["finished", "pending"]}},
              "required": ["status", "nonce", "phase"]}
    prompt = f'This is an isolated CLI integration probe. Work only in {workspace}. Return the provided JSON schema with status CLI_OK and nonce {nonce}. '
    if case == "structured":
        prompt += 'Use no tools. Return phase finished.'
    elif case == "files":
        checkpoint = {"current_claim": "The local probe file exists.", "evidence_paths": ["probe-evidence.txt"],
                      "attempts": ["Write and read the probe file."], "remaining_work": [],
                      "next_step": "Return the structured probe result.", "progress_state": "ready_to_submit"}
        prompt += ('Write probe-evidence.txt containing exactly ' + nonce + ', read it back, then write checkpoint.json as ' +
                   json.dumps(checkpoint) + '. Return phase finished after verifying both files. ')
        if scholarly:
            prompt += 'Also call the provided scholarly list_sources tool once. Do not search or fetch literature.'
    elif case == "background":
        prompt += ('Use Bash to start exactly one background command (run_in_background=true) which waits 5 seconds '
                   'and writes completed.txt containing exactly ' + nonce + '. Write a local phase-pending.json checkpoint while it runs. '
                   'Wait for the native completion notification for that task, then read completed.txt and submit phase finished. '
                   'Keep the CLI invocation active until the job finishes. Do not submit the final JSON while it is still pending; '
                   'print mode may terminate outstanding background work when the final result is returned. Do not start agents or another model.')
    else:
        prompt += 'Start a Bash command that waits 120 seconds. The local runner will deliberately stop this probe while that tool is active. Do not start background agents.'
    stop = False
    native_tool_names = []
    def observe_event(event):
        nonlocal stop
        content = event.get("message", {}).get("content", []) if isinstance(event.get("message"), dict) else []
        for block in content if isinstance(content, list) else []:
            if isinstance(block, dict) and block.get("type") == "tool_use":
                native_tool_names.append(block.get("name"))
                if case == "stop":
                    stop = True
        item = event.get("item", {})
        if event.get("type") == "item.started" and isinstance(item, dict):
            if item.get("type") == "mcp_tool_call":
                server, tool = item.get("server"), item.get("tool")
                if isinstance(server, str) and isinstance(tool, str):
                    native_tool_names.append(f"mcp__{server}__{tool}")
            if case == "stop" and item.get("type") == "command_execution":
                stop = True
    def observe(batch):
        for event in batch.events:
            observe_event(event)
    server = resolve_scholarly_server(None, start=Path.cwd(), codex_home=codex_home) if scholarly else None
    runner = ModelRunner(jobs=ports.jobs, clock=ports.clock, environment=environment, host_id=host_id)
    routed_model = model if provider_for(model) == provider else "claude:" + model
    result = runner.run(prompt=prompt, output_schema=schema, workspace=workspace, evidence_dir=root / "evidence",
        model=routed_model, effort=effort, timeout_seconds=None, claude_only_assigned_model=only_assigned,
        scholarly_server=server, on_observation=observe, should_stop=lambda: stop)
    collected = result.get("execution", {}).get("collect", {})
    parsed = collected.get("jsonl", {})
    checks = {"local_termination": collected.get("termination_barrier", {}).get("confirmed") is True}
    if case == "stop":
        checks["requested_stop"] = stop and result["status"] == "stopped"
    else:
        checks["structured_result"] = result["status"] == "completed" and result["output"] == {"status": "CLI_OK", "nonce": nonce, "phase": "finished"}
    if case == "files":
        checks["preserved_file"] = (workspace / "probe-evidence.txt").is_file() and (workspace / "probe-evidence.txt").read_text(encoding="utf-8").strip() == nonce
        checks["checkpoint"] = read_checkpoint(workspace, clock=ports.clock)["status"] == "valid"
        if scholarly:
            checks["scholarly_actual_tool"] = "mcp__scholarly__list_sources" in native_tool_names
    if case == "background":
        checks["native_background_start"] = any(row["event"].get("subtype") == "task_started" for row in parsed.get("background_events", []))
        checks["background_completed_before_result"] = background_completed_before_result(parsed)
        checks["completed_file"] = (workspace / "completed.txt").is_file() and (workspace / "completed.txt").read_text(encoding="utf-8").strip() == nonce
    if provider == "claude" and only_assigned and case != "stop":
        checks["reported_models"] = bool(parsed.get("reported_models")) and parsed["reported_models"] == [model]
    report = {"case": case, "passed": all(checks.values()), "checks": checks, "result": json_safe(result),
              "actual_tool_names": native_tool_names}
    (root / "report.json").write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
    return {"case": case, "passed": report["passed"], "checks": checks, "report": str(root / "report.json")}
